// ===== COOKING INSTRUCTIONS =====
var RECIPE_COOKING_DATA = {
"Classic Oatmeal with Berries":{prepTime:"5 mins",cookTime:"10 mins",steps:["Bring the whole milk and about 1 1/4 cups of water to a gentle simmer in a saucepan over medium heat.","Add the rolled oats and the cinnamon, stirring for 5-7 minutes until creamy.","Slice the banana into rounds.","Transfer the oatmeal to a bowl and top with the blueberries and banana slices.","Top with the granola and strawberries, then drizzle with the honey and maple syrup."]},
"Scrambled Eggs & Toast":{prepTime:"5 mins",cookTime:"8 mins",steps:["Crack eggs into a bowl, add a splash of whole milk, and whisk until smooth.","Toast the whole wheat bread slices.","Melt butter in a non-stick pan over medium-low heat.","Pour in eggs and stir gently with a spatula, forming soft curds.","When eggs are nearly set, remove from heat and stir in cheddar cheese.","Serve eggs alongside toast."]},
"Greek Yogurt Parfait":{prepTime:"5 mins",cookTime:"0 mins",steps:["Wash and slice the strawberries and slice the banana into rounds.","Spoon half the greek yogurt into a bowl or glass.","Add a layer of granola, half the strawberries and the blueberries.","Add the remaining yogurt and top with the rest of the granola, the strawberries and the banana.","Drizzle with the honey and serve immediately."]},
"Avocado Toast with Egg":{prepTime:"5 mins",cookTime:"8 mins",steps:["Toast the whole wheat bread slices until golden.","Poach the eggs in barely simmering water until the whites are just set.","Mash the avocado with a fork, squeeze in the lemon juice, and season with salt, black pepper, and chili flakes.","Spread the mashed avocado on the toast and top with the poached eggs."]},
"Protein Pancakes":{prepTime:"5 mins",cookTime:"12 mins",steps:["Blend the rolled oats into a flour in a blender.","Add the eggs, mashed banana, greek yogurt, baking powder, cinnamon, and a splash of whole milk to the blender and mix until smooth.","Heat a non-stick pan over medium heat and melt the butter to grease it.","Pour batter to form 3 pancakes and cook 2-3 minutes per side until golden.","Stack the pancakes and top with the granola, blueberries, and strawberries, then drizzle with the maple syrup."]},
"Breakfast Burrito":{prepTime:"10 mins",cookTime:"10 mins",steps:["Scramble the eggs in a pan over medium heat until just set.","Soak the dried black beans overnight and simmer them in fresh water until tender, about an hour (batch-cook them for the week), then warm them in a small saucepan.","Warm the tortilla in a dry pan for 30 seconds per side.","Layer scrambled eggs, black beans, cheddar cheese, and sliced avocado on the tortilla.","Roll up tightly, tucking in the sides, and serve."]},
"Shakshuka Breakfast":{prepTime:"10 mins",cookTime:"20 mins",steps:["Dice the onion and bell pepper and mince the garlic.","Soften the onion and bell pepper in a wide pan, then add the garlic, the cumin, paprika, cayenne and caraway and fry a minute until fragrant - cumin and caraway together are the Tunisian signature.","Pour in the tomato sauce, season with salt and black pepper, and simmer 10 minutes until thick enough to hold a spoon trail.","Make wells in the sauce and crack the eggs into them.","Cover and cook 5-8 minutes until the whites are set but the yolks are still soft.","Crumble the feta over the top and serve with the warmed pita for scooping."]},
"Japanese Tamagoyaki":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Whisk the eggs with the soy sauce, mirin, sugar and a pinch of salt until just combined, without beating air into them.","Heat a rectangular tamagoyaki pan over medium-low heat and brush it with vegetable oil.","Pour in a thin layer of the egg mixture, cook until just set, then roll it to one side of the pan.","Brush the pan with more vegetable oil, pour in another thin layer, and roll each new layer around the previous one until the egg is used up.","Roll the hot omelette in a bamboo mat to set its shape, then slice it into rounds and serve with the rice, a bowl of miso soup made by whisking the miso paste into hot water taken off the boil, and sliced green onion."]},
"Smoothie Bowl":{prepTime:"10 mins",cookTime:"0 mins",steps:["Peel and freeze the banana in advance for best results.","Blend the frozen banana, blueberries, greek yogurt, and a splash of whole milk until thick and creamy.","Pour into a bowl.","Top with the granola, rolled oats, mango, and strawberries, then drizzle with the honey and maple syrup.","Serve immediately before it melts."]},
"Egg & Potato Paratha":{prepTime:"25 mins",cookTime:"15 mins",steps:["Knead the flour with a splash of warm water into a soft dough, then cover and rest it for 20 minutes.","Boil the potato until fork-tender, about 12 minutes, then peel and mash it roughly.","Mix the mashed potato with very finely minced onion, grated ginger, chopped serrano chile, chopped cilantro, a squeeze of lemon juice standing in for amchur, cumin, chili powder and salt.","Flatten a ball of dough in your palm, seal the potato filling inside it, and roll it out into a 6-inch round.","Griddle the stuffed paratha on a hot dry pan, smearing it with butter, until golden and blistered on both sides.","Fry the eggs in the remaining butter, season them with black pepper, and serve alongside the hot paratha with the last of the lemon juice spooned over."]},
"Chilaquiles":{prepTime:"15 mins",cookTime:"20 mins",steps:["Cut the corn tortillas into triangles and fry them in a little of the vegetable oil until crisp and golden, or bake them for the lighter version.","Toast the guajillo chile in a dry pan until fragrant, soak it in hot water for ten minutes, then blend it with the tomato, half the onion, the garlic powder, cayenne and cumin.","Fry the blended salsa in the remaining vegetable oil over medium-high heat until it darkens and thickens, about eight minutes, then season with salt and black pepper.","Fry the eggs in a separate pan to your liking.","Fold the tortilla chips into the sauce only seconds before serving so they keep their bite.","Plate the sauced chips and top with the fried eggs, thin slivers of the remaining raw white onion, sliced avocado and crumbled queso fresco.","Thin the Greek yogurt with a splash of water and drizzle it over as a stand-in for Mexican crema."]},
"French Toast":{prepTime:"5 mins",cookTime:"10 mins",steps:["Whisk together the eggs, whole milk, cinnamon, vanilla extract, and a pinch of salt in a shallow dish.","Dip the bread slices in the custard, soaking each side for 20-30 seconds.","Melt the butter in a pan over medium heat.","Cook the bread slices 2-3 minutes per side until golden brown.","Serve topped with the sliced strawberries, blueberries, sliced banana, granola, and rolled oats. Drizzle with the maple syrup."]},
"Huevos Rancheros":{prepTime:"10 mins",cookTime:"20 mins",steps:["Lightly fry the corn tortillas in a little of the vegetable oil, about twenty seconds per side, until golden with slightly crisp edges.","Soak the dried black beans overnight and simmer them until soft, about an hour, then mash them into refried beans with a splash of their cooking liquid and a pinch of salt.","Fry the chopped onion, garlic powder and minced serrano chile in the remaining oil, add the tomato sauce, and simmer until it darkens and thickens into a salsa ranchera, about ten minutes.","Season the salsa with salt and black pepper.","Fry the eggs sunny-side up in the same pan.","Layer the fried tortillas with the refried beans, set the eggs on top and spoon the salsa ranchera over.","Finish with sliced avocado and crumbled queso fresco."]},
"Grilled Chicken & Rice Bowl":{prepTime:"10 mins",cookTime:"30 mins",steps:["Cook brown rice according to package directions.","Season the chicken with salt, pepper, and a drizzle of olive oil.","Grill or pan-sear chicken over medium-high heat, 6-7 minutes per side until cooked through.","Steam or blanch broccoli florets until tender-crisp, about 4 minutes.","Slice the chicken and assemble bowls with rice, broccoli, and chicken.","Drizzle with remaining olive oil."]},
"Tagliatelle al Ragu":{prepTime:"15 mins",cookTime:"2 hrs",steps:["Chop the onion, carrot and celery very fine and sweat them in the olive oil over medium-low heat until soft and sweet, about 10 minutes - this soffritto is the base of the ragu.","Dice the pork belly and render it into the soffritto until its fat runs.","Add the ground beef, break it up and brown it properly.","Pour in the white wine and cook until it has completely evaporated.","Add the tomato sauce, season with salt and black pepper, and simmer very gently for 2 hours.","Stir the whole milk in at the halfway point and let it cook away - the milk is what makes a ragu tender rather than sharp.","Cook the pasta as tagliatelle, toss it with the ragu, and finish with the grated parmesan."]},
"Chicken Burrito Bowl":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook the brown rice according to package directions, then toss it while still warm with the chopped cilantro and a squeeze of the lime juice.","Season the chicken thigh with cumin and chipotle powder, then grill or pan-sear it until cooked through, about 6-7 minutes per side.","Soak the dried black beans overnight and simmer them until tender, about an hour, then warm them in a small pot with a pinch of salt and black pepper.","Dice the tomato and red onion and toss them with the rest of the lime juice for a quick pico de gallo.","Cook the corn in a hot dry pan for 2 minutes for a charred effect, and slice the avocado.","Slice the chicken and build the bowl with the cilantro-lime rice, beans, corn, pico de gallo and avocado."]},
"Teriyaki Salmon Bowl":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook the white rice according to package directions.","Pat the salmon dry, season it with salt and dust it lightly with the flour so the tare will cling.","Heat the vegetable oil in a pan and sear the salmon skin-side down for 4 minutes, then flip it and cook 3 minutes more.","Whisk the soy sauce, mirin and sake together, pour the tare into the pan and spoon it over the salmon until it reduces to a glossy glaze.","Cook the edamame in boiling water for 3 minutes, then drain.","Assemble the bowl with the rice, the glazed salmon and the edamame."]},
"Chicken Tikka Masala":{prepTime:"15 mins",cookTime:"30 mins",steps:["Cut the chicken into bite-sized pieces and marinate it in the greek yogurt with half the grated ginger and minced garlic, paprika, garam masala, cumin, coriander, turmeric and salt for at least 4 hours.","Cook the basmati rice according to package directions.","Spread the marinated chicken on a rack and broil or grill on high until the edges char, then set it aside.","Heat the olive oil and fry the diced onion until deep golden, then add the remaining ginger and garlic and cook for a minute.","Add the tomato sauce and the ground spices and cook until the sauce thickens and the oil separates.","Return the charred chicken to the sauce and simmer for 10 minutes, then stir in the evaporated milk off the heat.","Finish with chopped cilantro and serve over the basmati rice."]},
"Falafel Plate":{prepTime:"20 mins",cookTime:"15 mins",steps:["Soak the dried chickpeas in plenty of cold water for at least 12 hours. Do not use canned or cooked chickpeas and never boil them - falafel is made from raw soaked chickpeas, and cooked ones turn the mixture to paste that falls apart in the oil.","Drain the chickpeas well and grind them with the onion, garlic, parsley and cilantro to a coarse, sandy texture.","Season with the cumin, coriander powder, salt and black pepper and rest the mixture 30 minutes.","Shape into small patties and shallow-fry in the vegetable oil until deep brown and crisp on both sides.","Slice the cucumber and loosen the tahini with cold water and a little salt into a pourable sauce.","Serve the falafel with the hummus, the tahini sauce, the cucumber and the warm pita."]},
"Greek Chicken Salad":{prepTime:"15 mins",cookTime:"12 mins",steps:["Season the chicken breast with salt, black pepper and half the oregano and grill it, then slice it.","Dice the tomato, cucumber and bell pepper into rough chunks and thinly slice the red onion.","Tear the romaine lettuce.","Toss the vegetables with the olive oil, the lemon juice and the remaining oregano.","Top with the sliced chicken and the feta in a slab rather than crumbled, the way a horiatiki is served."]},
"Beef Stir Fry":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook the brown rice according to package directions.","Slice the beef sirloin into thin strips against the grain.","Slice the bell pepper, cut the broccoli into small florets, trim the asparagus into short lengths, and mince the garlic and ginger.","Heat the vegetable oil in a wok over high heat and sear the beef strips for 2 minutes, then set aside.","Stir-fry the broccoli for 2 minutes, then add the bell pepper and asparagus for a further 2 minutes.","Add the minced garlic and ginger and stir-fry for 30 seconds until fragrant.","Return the beef, add the soy sauce, season with salt and black pepper, and toss together.","Finish off the heat with the sesame oil and serve over the rice."]},
"Carnitas Tacos":{prepTime:"15 mins",cookTime:"3 hrs",steps:["Season the pork shoulder generously with salt, black pepper, cumin and Mexican oregano.","Cook it gently in a heavy pot, submerged in its own rendered fat, with the garlic powder, bay leaves and the juice and peel of the orange, at a bare simmer for about three hours until fork-tender.","Shred the pork with two forks.","Spread the shredded pork out in a hot dry pan or under a broiler until the edges caramelise and crisp - this is what makes it carnitas rather than braised pork.","Warm the corn tortillas in a dry pan for thirty seconds per side.","Fill the tortillas with the crisped pork and finely chopped white onion and cilantro.","Sprinkle the lime juice over the tacos and serve."]},
"Miso Ramen":{prepTime:"20 mins",cookTime:"60 mins",steps:["Roll the pork belly into a tight log and braise it gently in the soy sauce, mirin and sake with just enough water to cover, about 45 minutes, until tender; cool it and slice it into chashu rounds, reserving the braising liquid.","Soft-boil the egg for 6-7 minutes, peel and halve it, then steep the halves in the reserved braising liquid to make ajitama.","Simmer the shiitake mushroom in about 1 1/2 cups of water for 15 minutes to build an umami-rich broth, then lift the mushroom out and slice it.","Cook the ramen noodles in a separate pot of boiling water until springy, about 3 minutes, and drain them well.","Bloom the grated garlic and ginger in the sesame oil over low heat, stir in the miso paste to make the tare, then loosen the tare with the hot broth and season with salt and white pepper.","Blanch the bean sprouts for 30 seconds and warm the corn through.","Pour the broth over the noodles and top with the chashu, the ajitama, the bean sprouts, corn, sliced shiitake, sliced green onion, a sheet of nori and a knob of butter."]},
"Palak Paneer":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook the basmati rice according to package directions.","Blanch the spinach in boiling water for 1 minute only, then drop it straight into ice water so it keeps its colour.","Blend the drained spinach with the garlic, ginger and serrano chile into a smooth green puree.","Melt the butter in a pan and bloom whole cumin seeds until they crackle, then add the diced onion and fry until golden.","Add the diced tomato, turmeric and coriander and cook until the tomato breaks down and the fat separates.","Stir in the spinach puree and simmer for only 5 minutes so it stays bright.","Add the cubed paneer, stir in the evaporated milk, and sprinkle the garam masala in at the very end off the heat. Finish with cilantro and serve over the rice."]},
"Shawarma Bowl":{prepTime:"20 mins",cookTime:"20 mins",steps:["Slice the chicken thigh into strips and marinate it with the greek yogurt, the lemon juice, the minced garlic, the red wine vinegar and the cumin, paprika, turmeric, cinnamon, allspice, salt and black pepper. Give it at least 30 minutes - the yogurt-and-acid marinade is what makes shawarma tender and is the step that was missing.","Cook the white rice according to package directions.","Sear the marinated chicken hard in a very hot pan without crowding it, so the edges char the way they would coming off the spit.","Slice the cucumber. Cook the dried chickpeas (soaked overnight and simmered until tender, about an hour) and keep them warm.","Build the bowl with the rice, the charred chicken, the chickpeas and the cucumber, and spoon the hummus alongside."]},
"Kimchi Fried Rice":{prepTime:"5 mins",cookTime:"10 mins",steps:["Dice the pork belly into small pieces and slice the green onion.","Render the pork belly in a dry hot wok until browned and crisp, about 4 minutes - it releases enough fat to fry in.","Add the chopped kimchi with its juice, the gochujang and a pinch of gochugaru. Stir-fry 2 minutes until the kimchi softens and deepens in colour.","Add cold day-old white rice and toss over high heat, breaking up any clumps. Season with salt and black pepper.","Push the rice to the side and fry the egg in the centre of the wok.","Off the heat, stir the sesame oil through. Plate topped with the fried egg and the sliced green onion."]},
"Lamb & Lentil Soup":{prepTime:"15 mins",cookTime:"35 mins",steps:["Dice the onion, carrot and potato and mince the garlic.","Brown the ground lamb in the olive oil in a heavy pot, breaking it up.","Add the onion, garlic and carrot and cook 2 minutes, then stir in the cumin and toast it 30 seconds - blooming the cumin in the fat is what gives the soup its depth.","Add the red lentils, the diced potato, the tomato sauce and about 1 1/2 cups of water. Stir to combine.","Simmer 25-30 minutes until the lentils have collapsed and the potato is tender. Season with salt and black pepper.","Serve hot."]},
"Pork & Avocado Wrap":{prepTime:"10 mins",cookTime:"10 mins",steps:["Season the pork loin with salt, black pepper, and smoked paprika, then slice it thinly.","Heat the olive oil in a hot pan and sear the pork for 2-3 minutes per side.","Warm the whole wheat tortilla in a dry pan or microwave for 15 seconds.","Slice the avocado and the tomato.","Layer the seared pork on the tortilla, then add the spinach, avocado, and tomato.","Roll up tightly, tucking in the sides. Slice in half and serve."]},
"Shrimp Primavera":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook the spaghetti in well-salted water until al dente, reserving a little of the water.","Slice the zucchini, trim and cut the asparagus into short lengths.","Warm the olive oil in a pan and cook the shrimp 1-2 minutes per side until just pink, then set them aside.","Add the zucchini, asparagus and green peas to the same pan and cook 3-4 minutes until bright and barely tender.","Return the shrimp, add the drained pasta and a splash of the pasta water, and toss. Season with salt and black pepper.","Tear the fresh basil over the top and finish with the grated parmesan."]},
"Shrimp Tacos":{prepTime:"15 mins",cookTime:"10 mins",steps:["Season the shrimp with salt, black pepper, garlic powder and paprika.","Sear the shrimp in a hot pan with the vegetable oil for one to two minutes per side, until just pink and opaque - shrimp overcook fast.","Whisk the Greek yogurt with the chipotle powder and a squeeze of lime juice into a chipotle crema.","Shred the cabbage thinly and toss it with the sliced red onion, chopped cilantro, lime juice, Mexican oregano and salt into a dressed slaw.","Warm the corn tortillas in a dry pan.","Lay the shrimp on the tortillas first, spoon the chipotle crema over, then top with the slaw and sliced avocado - sauce straight onto a corn tortilla tears it.","Serve with the remaining lime juice sprinkled over."]},
"Chicken and Vegetable Stir Fry":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook the brown rice according to package directions.","Cut the chicken breast into bite-sized pieces. Mince the garlic and grate the ginger.","Heat the vegetable oil in a wok over high heat and cook the chicken until golden on all sides, about 6-8 minutes.","Add the garlic and ginger and stir-fry 30 seconds until fragrant.","Add the broccoli florets, sliced carrot, green beans and edamame and stir-fry 4-5 minutes.","Splash in the soy sauce and toss, then take the wok off the heat and stir the sesame oil through at the end.","Season with salt and white pepper and serve over the rice."]},
"Lamb Kofta Plate":{prepTime:"20 mins",cookTime:"12 mins",steps:["Grate the yellow onion and squeeze the liquid out of it - wet onion makes the kofta fall apart on the grill.","Mix the ground lamb with the grated onion, the finely chopped parsley, the cumin, paprika, coriander powder, allspice, cinnamon, salt and black pepper, and work it until it turns slightly sticky.","Rest the mixture in the fridge 20 minutes, then shape it around skewers or into flattened fingers.","Grill or broil 5-6 minutes per side until charred outside and just cooked through.","Slice the red onion thinly for the garnish and loosen the tahini with cold water into a pourable sauce.","Serve the kofta with the hummus, the tahini sauce, the raw red onion and the warm pita."]},
"Japchae":{prepTime:"15 mins",cookTime:"15 mins",steps:["Soak the sweet potato noodles in warm water for 10 minutes, then boil 5-6 minutes, drain and cut with scissors.","Toss the hot drained noodles with half the soy sauce, the honey and half the sesame oil so they absorb the seasoning while warm.","Slice the beef sirloin into thin strips and marinate with the remaining soy sauce, the minced garlic, black pepper and the rest of the sesame oil.","Blanch the spinach for 30 seconds, drain and squeeze dry. Season with a little sesame oil and salt.","Julienne the carrot and bell pepper, slice the onion and the shiitake mushroom, and cut the green onion into short lengths.","Stir-fry the beef with the sliced shiitake for 2-3 minutes until browned, then remove to a bowl.","Stir-fry the onion, then the carrot, then the bell pepper one at a time, a minute each with a pinch of salt, removing each to the bowl before the next - cooking them separately is what keeps each vegetable its own colour and bite.","Toss the noodles, beef, spinach and vegetables together and scatter the green onion over."]},
"Brown Rice Power Bowl":{prepTime:"10 mins",cookTime:"30 mins",steps:["Cook the brown rice according to package directions.","Cube the sweet potato, toss it with half the olive oil, salt and black pepper, and roast at 200C for 25 minutes until caramelised at the edges.","Season the chicken breast and grill or pan-sear it, then slice it.","Wilt the spinach briefly.","Build the bowl with the rice, sweet potato, chicken and spinach, and dress it with the remaining olive oil."]},
"BBQ Chicken Plate":{prepTime:"10 mins",cookTime:"35 mins",steps:["Peel and cube the sweet potato, toss with the olive oil, and roast at 200\u00b0C (400\u00b0F) for 25 minutes.","Season the chicken breast with salt, black pepper, paprika, garlic powder and cayenne.","Grill or bake the chicken for 20-25 minutes until cooked through.","Brush the chicken with the BBQ sauce during the last 5 minutes of cooking.","Toss the coleslaw mix with the mayonnaise and a splash of red wine vinegar to dress it.","Rest the chicken for 5 minutes, then serve with the roasted sweet potato and the slaw."]},
"Chana Masala":{prepTime:"10 mins",cookTime:"30 mins",steps:["Cook the basmati rice according to package directions.","Heat the olive oil and crackle whole cumin seeds, a bay leaf and a bruised cardamom pod in it.","Add the sliced onion and fry it to a deep golden brown, then add the minced garlic, grated ginger and chopped serrano chile.","Add the diced fresh tomato and the tomato sauce along with the turmeric, coriander, chili powder and garam masala, and fry until the mixture darkens and the oil separates from the masala.","Add the chickpeas (soaked overnight and simmered until tender, about an hour) with just enough of their cooking water to cover them and simmer for 20 minutes, mashing a few against the side of the pan to thicken the gravy.","Take it off the heat and finish with a squeeze of lemon juice standing in for amchur and a handful of chopped cilantro. Serve with the rice."]},
"Poke Bowl":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cook the white rice and let it cool slightly.","Cut the ahi tuna into 2cm cubes.","Slice the onion very thinly and chop the green onion, then roughly chop the ogo seaweed.","Toss the tuna with the soy sauce, sesame oil, a good pinch of sea salt, the sliced onion, the green onion and the ogo seaweed.","Let the poke rest for 10 minutes so the shoyu marinade soaks in.","Spoon the poke over the rice and serve."]},
"Bulgogi Rice Bowl":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cook the white rice according to package directions.","Slice the beef sirloin thinly and marinate 10 minutes in the soy sauce, grated Asian pear, minced garlic, grated ginger, honey, sesame oil, black pepper and half the sliced green onion.","Julienne the carrot and slice the onion.","Cook the marinated beef with the sliced onion in a hot skillet for 3-4 minutes until caramelised, spooning the pan juices back over it.","Season with a pinch of salt and assemble the bowl with the rice, the bulgogi and its juices, and the carrot. Top with the remaining green onion and serve the kimchi on the side."]},
"Pork Fried Rice":{prepTime:"5 mins",cookTime:"12 mins",steps:["Use day-old cooked white rice for best results.","Dice the pork belly and render it in a hot dry wok until browned and the fat has run out, 3-4 minutes.","Add the diced carrot and stir-fry for 2-3 minutes until it softens.","Push everything to one side, scramble the eggs in the rendered fat, and break them into small pieces.","Add the rice and green peas and stir-fry for 3-4 minutes, chopping to separate the grains.","Season with the soy sauce, salt and white pepper, and toss to combine.","Off the heat, stir through the sliced green onion and the sesame oil. Serve immediately."]},
"Tuna Nicoise Salad":{prepTime:"15 mins",cookTime:"20 mins",steps:["Boil the potato until tender, then slice it while still warm.","Blanch the green beans 3 minutes and drop them into ice water.","Soft-boil the egg 7 minutes, peel and halve it.","Season the ahi tuna with salt and black pepper and sear it 1 minute per side, leaving it rare in the middle, then slice it.","Cut the tomato into wedges.","Whisk the olive oil with the red wine vinegar and a little salt and pepper into a dressing.","Arrange the potato, green beans, egg and tomato on a plate, lay the tuna over, and spoon the dressing across. No olives, by preference."]},
"Chicken Quesadilla":{prepTime:"10 mins",cookTime:"15 mins",steps:["Season the chicken breast with salt, black pepper and garlic powder, cook it in a hot pan until done, then dice it.","Blister the bell pepper and onion over high heat in a dry pan until the skins char in spots, then cut them into strips and toss with the Mexican oregano to make rajas con cebolla.","Lay the tortilla in a dry pan and cover half of it with the mozzarella, then the chicken, the rajas and the minced jalapeno.","Fold the tortilla over and cook 2-3 minutes per side until golden and the cheese has melted and pulls.","Rest for a minute, cut into wedges, and serve with the lime juice sprinkled over."]},
"Lamb & Hummus Wrap":{prepTime:"10 mins",cookTime:"12 mins",steps:["Brown the ground lamb with the cumin, paprika, salt and black pepper, then add the lemon juice off the heat.","Dice the tomato and cucumber and thinly slice the red onion.","Warm the tortilla in a dry pan.","Spread the hummus across the tortilla, lay the spinach over it, then the lamb, tomato, cucumber and red onion.","Roll it up tightly and serve."]},
"Chicken Caesar Salad":{prepTime:"10 mins",cookTime:"15 mins",steps:["Season the chicken breast with salt, black pepper, and garlic powder.","Grill or pan-sear the chicken 6-7 minutes per side until cooked through, then let it rest and slice.","Wash and chop the romaine lettuce.","Whisk the mayonnaise with the lemon juice, worcestershire sauce, a pinch of garlic powder, a little of the olive oil, and half the parmesan cheese into a smooth dressing, then toss it with the romaine.","Cube the whole wheat bread, toss it with the remaining olive oil, and toast until crisp to make croutons.","Top the salad with the sliced chicken, the remaining shaved parmesan cheese, and the croutons."]},
"Lamb Shawarma Wrap":{prepTime:"20 mins",cookTime:"20 mins",steps:["Slice the lamb shoulder thinly across the grain and marinate it with the red wine vinegar and the cumin, paprika, turmeric, cinnamon, allspice, salt and black pepper for at least 30 minutes.","Sear the lamb hard in a very hot pan in batches so it chars at the edges rather than steaming.","Slice the red onion thinly and chop the parsley.","Loosen the tahini with cold water and a squeeze of salt into a pourable sauce.","Warm the tortilla in a dry pan, lay the lamb down the middle, top with the red onion, parsley and tahini sauce, and roll it up tightly."]},
"Shrimp Fried Rice":{prepTime:"10 mins",cookTime:"10 mins",steps:["Use day-old cooked white rice for best results; jasmine is the rice this dish is made with.","Peel and devein the shrimp. Mince the garlic, cut the tomato into wedges, slice the green onion, and cut the cucumber into rounds to serve raw alongside.","Heat the vegetable oil in a wok over high heat and fry the garlic for about 20 seconds until fragrant.","Add the shrimp and toss constantly until just pink, then push them to one side of the wok.","Crack the egg into the empty side and scramble it, breaking it apart as it sets.","Add the rice and stir-fry hard, pressing out any clumps, then fold in the tomato and green onion.","Season with the fish sauce, the soy sauce for colour, the sugar, salt and white pepper, and toss until everything is coated.","Plate with the cucumber slices and the lime juice to add at the table, and add sliced serrano chile to taste."]},
"Butter Chicken":{prepTime:"15 mins",cookTime:"25 mins",steps:["Cut the chicken into bite-sized pieces and marinate them in the greek yogurt with the lemon juice, grated ginger, minced garlic, paprika, garam masala and salt for at least 4 hours.","Cook the basmati rice according to package directions.","Broil or grill the marinated chicken on high until the edges char, then set it aside.","Simmer the tomato sauce with the cumin, coriander and black pepper until it is thick and the fat begins to separate.","Whisk in the butter a piece at a time, then stir in the evaporated milk to make the makhani gravy.","Return the charred chicken to the gravy and simmer for 5 minutes, then finish with chopped cilantro and serve over the rice."]},
"Mediterranean Stuffed Peppers":{prepTime:"15 mins",cookTime:"35 mins",steps:["Cook the brown rice according to package directions.","Halve the bell peppers and remove the seeds.","Dice the onion and mince the garlic. Brown the ground beef with them until the onion is soft.","Mix the cooked rice into the beef with half the tomato sauce, the cumin, oregano, dried parsley, salt and black pepper.","Stuff the pepper halves with the mixture and top with the remaining tomato sauce.","Bake at 190C for 30 minutes, scattering the feta over for the last 5 minutes."]},
"Yangnyeom Chicken Bowl":{prepTime:"10 mins",cookTime:"30 mins",steps:["Cook the white rice according to package directions.","Pat the chicken breast dry and season with a little gochugaru, salt and black pepper.","Bake the chicken at 220C (425F) for 25-30 minutes, flipping halfway.","Make the yangnyeom sauce: simmer the gochujang, tomato sauce, honey, soy sauce, minced garlic, rice vinegar and sesame oil together for 2 minutes until glossy.","Slice the baked chicken and toss it in the hot sauce.","Serve over the rice."]},
"Spaghetti alle Vongole":{prepTime:"15 mins",cookTime:"15 mins",steps:["Scrub the clams and soak them in cold salted water for 20 minutes so they purge their grit.","Slice the garlic thin and warm it in the olive oil with the chili flakes over low heat until fragrant but not coloured.","Raise the heat, add the clams and the white wine, cover, and cook 3-4 minutes until they open. Discard any that stay shut.","Lift the clams out and strain their liquor through a fine sieve back into the pan - that liquor is the sauce and it is the whole point of the dish.","Cook the pasta as spaghetti until just short of al dente, then finish it in the pan with the clam liquor so it drinks the sauce up. Season with black pepper and only a little salt, since the clams are already saline.","Return the clams, toss through the chopped parsley, and serve. No cheese."]},
"Enchiladas Rojas de Pollo":{prepTime:"20 mins",cookTime:"30 mins",steps:["Stem and seed the guajillo and ancho chiles, toast them in a dry pan about 30 seconds a side until aromatic without letting them scorch, then soak them in hot water for 20 minutes.","Cook the white rice arroz-rojo style: toast it in a little of the vegetable oil, stir in a spoonful of the tomato sauce, then simmer it covered with about half a cup of water until tender.","Blend the soaked chiles with the garlic, Mexican oregano, cumin, salt and the remaining tomato sauce, loosening with a little of the chile soaking liquid until the sauce is smooth.","Heat most of the remaining vegetable oil in a pan and fry the blended sauce for about 5 minutes until it darkens and thickens, then season with black pepper.","Poach the chicken thigh until cooked through, shred it, and season it lightly with salt.","Pass each corn tortilla through the last of the hot oil for about 10 seconds a side so it softens without crisping, then dip it fully in the chile sauce.","Fill each tortilla with the shredded chicken, roll it up, and set it seam-side down on the plate.","Spoon the remaining sauce over the top, then finish with crumbled queso fresco, a drizzle of Greek yogurt loosened with a splash of water to stand in for crema, and thin rings of raw onion. Serve immediately with the rice."]},
"Sushi Bowl (Chirashi)":{prepTime:"20 mins",cookTime:"15 mins",steps:["Cook short-grain Japanese rice, then while it is still warm fold through a sushi-zu of rice vinegar, sugar and salt, cutting it in with a paddle rather than stirring, and fan it to cool so the grains stay glossy and separate.","Beat the egg, cook it as a paper-thin crepe in a lightly wiped pan, roll it and shred it into fine ribbons of kinshi tamago.","Slice the sashimi-grade salmon fillet and the ahi tuna into thin pieces across the grain.","Slice the cucumber and the avocado.","Cook the edamame in boiling water for 3 minutes and drain it.","Spread the seasoned rice in a bowl, scatter shredded nori over it, then arrange the salmon, ahi tuna, kinshi tamago, avocado, cucumber and edamame on top.","Serve with the soy sauce on the side."]},
"Aloo Gobi":{prepTime:"10 mins",cookTime:"25 mins",steps:["Cook the basmati rice according to package directions.","Peel and cube the potato and cut the cauliflower into florets.","Heat the olive oil and crackle whole cumin seeds in it, then add the grated ginger and chopped serrano chile.","Add the diced onion and fry until golden, then add the diced fresh tomato with the turmeric, coriander and chili powder and cook for 2 minutes.","Add the potato and cauliflower, toss to coat them in the masala, and cover for only 8 to 10 minutes until they soften.","Uncover and fry another 5 to 7 minutes, stirring rarely, so the edges brown and the sabzi cooks dry.","Take off the heat, sprinkle over the garam masala and chopped cilantro, and serve with the rice."]},
"Tabbouleh with Grilled Chicken":{prepTime:"20 mins",cookTime:"15 mins",steps:["Soak the bulgur in a little cold water for 15 minutes until it softens, then squeeze it dry. Tabbouleh uses only a small amount of bulgur - it is a parsley salad with grain in it, not a grain salad with herbs in it.","Chop the parsley very finely and dice the tomato and cucumber small.","Season the chicken breast with salt and black pepper and grill it, then slice it.","Toss the parsley, bulgur, tomato, cucumber, the cooked chickpeas (soaked overnight and simmered until tender, about an hour) and mint with the olive oil and the lemon juice.","Season, let it sit 10 minutes for the flavours to come together, and serve with the sliced chicken on top."]},
"Pork Tonkatsu":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Pound the pork loin to an even thickness and season it with salt and black pepper.","Set up a breading station of flour, beaten egg and panko breadcrumbs, then coat the pork in flour, dip it in the egg and press it firmly into the panko.","Heat the vegetable oil to 170C and deep-fry the cutlet for 5-6 minutes, turning once, until deep golden; drain it on a rack.","Shred the cabbage as finely as you can.","Rest the cutlet for 2 minutes, slice it crosswise into 1.5cm strips, and serve it with the rice, a mound of the raw shredded cabbage, the lemon juice to sprinkle over, a dab of karashi and the tonkatsu sauce."]},
"Thai Basil Chicken":{prepTime:"10 mins",cookTime:"10 mins",steps:["Cook the white rice according to package directions; jasmine is the rice this dish is served with.","Pound or mince the garlic together with the serrano chile into a rough paste.","Hand-chop the chicken thigh coarsely rather than dicing it, since the loose uneven texture is part of the dish.","Heat most of the vegetable oil in a wok over high heat, add the garlic and chile paste, and fry about 20 seconds until fragrant.","Add the chicken and stir-fry hard until browned and crisp at the edges.","Season with the fish sauce, the soy sauce for colour, the sugar, salt and white pepper, and toss to coat.","Kill the heat and fold in the basil, letting the residual heat wilt it rather than cooking it; holy basil is what the dish wants.","In a separate pan fry the egg in the remaining vegetable oil over high heat until the white is crisp at the edges and the yolk is still runny.","Serve the chicken over the rice with the fried egg on top."]},
"Tuscan White Bean Soup":{prepTime:"15 mins",cookTime:"40 mins",steps:["Chop the onion, carrot and celery fine and sweat them with the sliced garlic in the olive oil until soft - the soffritto comes first, before anything else goes in the pot.","Dice the pork belly and render it into the soffritto.","Add the white beans (soaked overnight and simmered until tender, about an hour), the tomato sauce, the thyme and about 3 cups of water. Season with salt and black pepper and simmer 30 minutes.","Mash or blend about a third of the beans and stir them back in - this is what thickens the soup instead of leaving it watery.","Shred the kale and simmer it in for the last 5 minutes.","Tear the bread into the pot and let it collapse into the soup for 5 minutes, then finish with a drizzle of olive oil."]},
"Kerala Chicken Curry with Green Mango":{prepTime:"15 mins",cookTime:"25 mins",steps:["Cook the white rice according to package directions.","Cut the chicken breast into pieces. Slice the onion, mince the ginger and garlic, and slit the serrano chile.","Heat the vegetable oil in a pan and soften the onion with the ginger, garlic and chile.","Stir in the cumin, coriander powder, turmeric and cayenne and fry for a minute until the raw smell goes.","Add the chicken and brown it, then pour in the coconut milk and simmer 12 minutes. Season with salt and black pepper.","Cut the mango into firm chunks and add it for the last 5 minutes only, so it holds its shape and stays tart rather than dissolving into sweetness.","Scatter with the chopped cilantro and serve over the rice."]},
"Grilled Salmon & Asparagus":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook the brown rice according to package directions.","Trim the asparagus ends and toss with about half the olive oil, salt and black pepper.","Season the salmon with salt, black pepper and half the lemon juice.","Grill the salmon and asparagus, or roast them at 200\u00b0C (400\u00b0F), for 12-15 minutes.","Make a quick nut-free pesto while the salmon cooks: pound or blitz the basil with the garlic and a pinch of salt, work in the grated parmesan, and loosen with the remaining olive oil.","Plate the brown rice, top with the salmon and asparagus, and spoon the pesto over the salmon.","Finish with the remaining lemon juice spooned over."]},
"Tacos de Picadillo":{prepTime:"15 mins",cookTime:"20 mins",steps:["Brown the ground beef in a skillet over medium-high heat with the diced onion, breaking the meat apart as it cooks.","Add the diced potato and chopped tomato with a splash of water, just enough to keep the pan from catching.","Simmer for twelve to fifteen minutes until the potato is tender and the sauce has reduced and thickened.","Season lightly with cumin, Mexican oregano, garlic powder, cayenne, salt and black pepper.","Warm the corn tortillas in a dry pan for thirty seconds per side.","Fill the tortillas with the picadillo and top with chopped cilantro and sliced avocado."]},
"Chicken Pesto Pasta":{prepTime:"10 mins",cookTime:"20 mins",steps:["Peel and dice the potato and trim the green beans.","Boil the pasta in well-salted water, adding the potato and green beans to the same pot so they cook alongside it - this is how pesto pasta is served in Liguria.","Season the chicken breast with salt and black pepper and pan-sear it until cooked through, then slice it.","Drain the pasta and vegetables, reserving a spoonful of the water.","Make the pesto while the pasta cooks: pound or blitz the basil with the garlic and a pinch of salt, work in most of the grated parmesan, and stream in the olive oil to a loose paste. No nuts - the cheese and oil carry it.","Off the heat, loosen the pesto with the reserved pasta water and toss it through the pasta, potato and green beans. Pesto is never cooked.","Top with the sliced chicken and the remaining parmesan."]},
"Katsu Curry":{prepTime:"15 mins",cookTime:"40 mins",steps:["Cook white rice according to package directions.","Melt the butter in a small pan, stir in about half the flour, and cook it gently for 15-20 minutes, stirring, until the roux turns golden brown; take it off the heat and stir the curry powder into it.","Dice the onion, carrot and potato, and grate the garlic and ginger.","Saute the garlic and ginger with the onion, carrot and potato, then cover with about 1 1/2 cups of water and simmer for 15 minutes until the potato is tender.","Whisk the roux into the vegetables, stir in the honey, soy sauce and tomato sauce, and simmer until the sauce thickens enough to coat the back of a spoon; season with salt and white pepper.","Pound the chicken breast to an even thickness, then coat it in the remaining flour, beaten egg and panko breadcrumbs.","Heat the vegetable oil to 170C and deep-fry the chicken for 4-5 minutes, turning once, until deep golden; drain it on a rack.","Slice the katsu crosswise and serve it over the rice with the curry sauce ladled alongside."]},
"Spicy Tuna Bowl":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cook the white rice, then fold in the rice vinegar, the sugar and a pinch of salt while it is still warm and let it cool to room temperature as shari.","Cut the ahi tuna into small cubes.","Mix the tuna with the mayonnaise, soy sauce, sesame oil and shichimi togarashi until it is evenly coated.","Slice the avocado and cucumber.","Assemble the bowl with the seasoned rice, the spicy tuna, the avocado and the cucumber."]},
"Steak & Sweet Potato":{prepTime:"10 mins",cookTime:"30 mins",steps:["Peel and cube the sweet potato, toss with the olive oil, salt and black pepper, and roast at 200\u00b0C (400\u00b0F) for 25 minutes.","Season the beef sirloin with salt and black pepper.","Sear the steak in a hot dry pan for 3-4 minutes per side for medium, adding the butter for the last minute and spooning it over the steak.","Let the steak rest for 5 minutes, then slice.","Steam the broccoli until tender-crisp, about 4 minutes, and season with salt and pepper.","Serve the sliced steak with the roasted sweet potato and broccoli."]},
"Larb Gai":{prepTime:"15 mins",cookTime:"15 mins",steps:["Dry-toast 8 g of the raw white rice in a pan over medium heat until deep golden and nutty, then grind it coarsely; this is khao khua, the toasted rice powder that gives larb its texture.","Cook the remaining white rice according to package directions to serve alongside.","Mince the chicken breast finely by hand.","Cook the minced chicken in a splash of water over high heat, stirring to keep it loose, until just cooked through; larb meat is simmered in a little liquid, never fried in oil.","While the chicken is still warm, toss it with the lime juice, fish sauce, sugar, salt and the toasted chili flakes.","Fold in the sliced shallot, green onion, cilantro, mint and the khao khua.","Spoon into romaine lettuce cups and serve with the rice on the side."]},
"Dal Tadka":{prepTime:"10 mins",cookTime:"30 mins",steps:["Cook the white rice according to package directions.","Rinse the toor dal and boil it with the turmeric, a little salt and about 1 1/4 cups of water until soft, roughly 20 minutes, then whisk it smooth. Cooking the turmeric with the lentils is what colours the dal itself rather than just the topping.","Dice the onion, chop the tomato, mince the garlic and ginger and slit the serrano chile.","Heat the butter in a small pan until it foams, then crackle the cumin in it - this is the tadka, and it starts with whole spice in hot fat, not with onion.","Add the garlic, ginger and chile and fry to pale gold, then the onion until golden, then the tomato and chili powder and cook it down 2 minutes.","Pour the sizzling tadka over the cooked dal, stir it through, season with black pepper, and finish with the chopped cilantro. Serve with the rice."]},
"Baba Ganoush Plate":{prepTime:"10 mins",cookTime:"25 mins",steps:["Char the whole eggplant directly over a gas flame or on a hot grill, turning it, until the skin is blackened all over and the flesh has collapsed. The smoke is the dish - an oven-roasted eggplant makes a dip, not baba ganoush.","Let it cool, then peel off the burnt skin and drain the flesh in a sieve so the dip is not watery.","Mash the eggplant with the tahini, the crushed garlic, the lemon juice, the cumin, salt and black pepper - mash by hand rather than blending, so it keeps some texture.","Spread on a plate, pour the olive oil over the top, and serve with the sliced cucumber and the warm pita."]},
"Dakgalbi":{prepTime:"15 mins",cookTime:"20 mins",steps:["Cook the white rice according to package directions and set it aside.","Cut the chicken thigh into bite-sized pieces.","Peel and cube the sweet potato, slice the cabbage and the onion, and cut the green onion into short lengths.","Mix the gochujang, gochugaru, soy sauce, honey, minced garlic, ground ginger, curry powder and sesame oil into a sauce - the pinch of curry powder is the Chuncheon signature.","Toss the chicken in the sauce and stir-fry it in a wide pan until nearly cooked.","Add the sweet potato, cabbage, onion, tteok and sweet potato noodles. Cook 10-12 minutes until the vegetables are tender, the tteok is chewy and the noodles are cooked through. Season with salt.","Stir the perilla leaves and green onion through at the very end.","When the chicken is gone, add the cooked rice to the pan and fry it in the remaining sauce. Serve with the kimchi."]},
"Pork Milanese":{prepTime:"15 mins",cookTime:"15 mins",steps:["Pound the pork loin thin and season it with salt and black pepper.","Set out the flour, the beaten egg and the breadcrumbs, and coat the pork in that order, pressing the crumbs on firmly.","Melt the butter in a large skillet over medium heat until it foams - a milanese is fried in butter, not oil, and that is most of its character.","Fry the breaded pork 3-4 minutes per side until deep golden, then drain it briefly.","Wilt the spinach in the same pan.","Serve with the lemon juice sprinkled over and the spinach alongside. Serve it dry: a breaded cutlet served under a sauce is a different dish entirely."]},
"Enfrijoladas":{prepTime:"10 mins",cookTime:"30 mins",steps:["Simmer the black beans until soft with half the onion, the garlic and the epazote, starting with about a cup of water and topping up so the beans stay just covered.","Blend the cooked beans with their liquid, the chipotle powder, Mexican oregano and cumin until completely smooth.","Heat the vegetable oil in a wide pan and fry the bean puree for about 5 minutes until it thickens into a coating sauce, then season with salt and black pepper.","Warm the corn tortillas in the same pan, about 15 seconds a side, until pliable.","Dip each tortilla in the bean sauce to coat both sides, fold it in half, and lay it on the plate.","Top with crumbled queso fresco, thin rings of the remaining raw onion, sliced avocado and a squeeze of lime juice."]},
"Salmon Misoyaki Bento":{prepTime:"10 mins",cookTime:"20 mins",steps:["Whisk the miso paste, mirin, sake and soy sauce into a marinade and coat the salmon fillet. Leave it 20 minutes, or overnight if you have it.","Cook the white rice according to package directions.","Slice the cucumber thinly, salt it, squeeze out the water and dress it with the rice vinegar - this is the tsukemono for the pickle slot of the box.","Wipe the excess marinade off the salmon and grill or pan-sear it 4 minutes per side, watching it closely because the miso catches quickly.","Steam the broccoli 4 minutes until tender-crisp, and boil the edamame 3 minutes and drain.","Pack the rice, salmon, broccoli, edamame and cucumber pickle into a bento box."]},
"Chicken Alfredo":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook the fettuccine in well-salted water until al dente and reserve about half a cup of the starchy water.","Season the chicken thigh with salt and black pepper, sear it until cooked through, and slice it.","Trim the asparagus and cook it briefly in the pasta water.","Melt the butter in a large pan over low heat - no garlic, which belongs to an American alfredo and not to the Roman original.","Add the drained fettuccine with a splash of the reserved pasta water and the grated parmesan, and toss hard off the heat until the butter, cheese and water emulsify into a glossy sauce.","Top with the sliced chicken and the asparagus."]},
"Lamb Biryani":{prepTime:"20 mins",cookTime:"40 mins",steps:["Slice the onion thin and fry it in the vegetable oil until deep golden and crisp. Lift it out onto paper - this is the birista, and it is folded through the dish rather than used as decoration.","Cube the lamb shoulder. Marinate it in the greek yogurt with the minced garlic and ginger, the cumin, garam masala, black pepper, salt, the lemon juice, half the birista, half the mint and half the cilantro.","Wash and soak the basmati rice 10 minutes, then parboil it with the cardamom, cinnamon and bay leaf until 70% cooked. Drain.","Cook the marinated lamb in a heavy pot until the yogurt tightens around the meat and the fat separates, about 20 minutes.","Steep the saffron in a spoonful of warm water.","Layer the parboiled rice over the lamb. Scatter the remaining birista, mint and cilantro over the top and drizzle the saffron water across the surface.","Cover tightly and cook on low heat 15-20 minutes, then fluff gently from the edge inward and serve."]},
"Shrimp & Feta Salad":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook the brown rice according to package directions.","Sear the shrimp in a little of the olive oil, 2 minutes per side, until just pink. Season with salt and black pepper.","Dice the tomato and cucumber and thinly slice the red onion.","Whisk the remaining olive oil with the lemon juice and the oregano.","Toss the rice, vegetables and shrimp with the dressing and crumble the feta over the top."]},
"Meatball Sub":{prepTime:"15 mins",cookTime:"20 mins",steps:["Mix the ground beef with the panko breadcrumbs, grated parmesan cheese, salt, black pepper, garlic powder, oregano, dried basil, and a beaten egg, then form into meatballs.","Brown the meatballs in a pan on all sides, about 5 minutes.","Add the tomato sauce, cover, and simmer for 15 minutes until the meatballs are cooked through.","Split the whole wheat bread lengthwise into a roll shape and toast lightly.","Fill the toasted bread with the meatballs and sauce.","Top with sliced mozzarella cheese and broil briefly until the cheese melts."]},
"Chicken Shawarma Plate":{prepTime:"20 mins",cookTime:"20 mins",steps:["Slice the chicken breast into strips and marinate at least 30 minutes with the greek yogurt, the lemon juice, the minced garlic, the red wine vinegar, the olive oil and the cumin, paprika, turmeric, cinnamon, allspice, coriander powder, cardamom, salt and black pepper.","Sear the chicken in a very hot pan in batches, leaving it alone long enough to char at the edges.","Slice the cucumber and loosen the tahini with cold water into a pourable sauce.","Warm the pita.","Plate the chicken with the hummus, the tahini sauce, the cucumber and the pita."]},
"Shrimp Fra Diavolo":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook the pasta in well-salted water until al dente.","Dice the onion and slice the garlic.","Warm the olive oil and soften the onion, then add the garlic and the chili flakes - fra diavolo means brother devil and the heat is the whole point, so do not be shy with them.","Pour in the white wine and cook until it has evaporated.","Add the tomato sauce and simmer 10 minutes, seasoning with salt and black pepper.","Add the shrimp and cook 2-3 minutes until just pink.","Toss with the drained pasta and finish with the chopped parsley off the heat."]},
"Cobb Salad":{prepTime:"15 mins",cookTime:"20 mins",steps:["Season and grill or pan-sear the chicken breast until cooked through, then dice.","Hard-boil the egg for 10 minutes, then peel and quarter it.","Fry the bacon until very crisp, drain it on paper towel, and crumble.","Dice the avocado and the tomato.","Chop the romaine lettuce and arrange it on a plate.","Arrange rows of chicken, egg, avocado, tomato, crumbled bacon, and crumbled blue cheese on the lettuce.","Whisk the olive oil with the red wine vinegar, salt, and black pepper into a vinaigrette, drizzle it over the salad, and scatter with sliced green onion."]},
"Vegetable Maki":{prepTime:"20 mins",cookTime:"15 mins",steps:["Cook the white rice, then fold through the rice vinegar, sugar and salt while it is still warm to make shari. Let it cool to room temperature.","Beat the egg, cook it as a thin sheet in a non-stick pan, and slice it into long strips.","Julienne the cucumber and carrot.","Lay a sheet of nori on a rolling mat and spread the seasoned rice over it, leaving a bare strip along the far edge.","Line up the cucumber, carrot and egg strips across the rice, then roll tightly and seal the bare edge with a little water.","Cut the roll into 8 pieces and serve with the soy sauce."]},
"Tinga de Pollo":{prepTime:"15 mins",cookTime:"30 mins",steps:["Poach the chicken breast in lightly salted water until just cooked through, about 15 minutes, then shred it with two forks and keep a little of the poaching broth.","Blend the tomato with the garlic, chipotle powder, Mexican oregano and cumin until smooth.","Slice half the onion thinly and fry it in the vegetable oil until softened and translucent.","Pour the blended sauce into the pan and cook it down for about 10 minutes until it darkens and thickens, loosening it with a splash of the reserved broth if it tightens too far. Season with salt and black pepper.","Return the shredded chicken to the sauce and simmer 5 minutes so it takes up the tinga.","Warm the corn tortillas on a dry pan and pile the tinga on top.","Finish with the rest of the onion chopped raw, the chopped cilantro and a squeeze of lime juice."]},
"Minestrone Soup":{prepTime:"20 mins",cookTime:"40 mins",steps:["Chop the onion, celery and carrot fine and sweat them in the olive oil over medium-low heat until soft - a minestrone starts from a soffritto, not from everything going in at once.","Dice the pork belly and render it into the soffritto.","Dice the zucchini, eggplant and potato and add them with the tomato sauce, the white beans (soaked overnight and simmered until tender, about an hour), the bay leaf and about 3 cups of water. Season with salt and black pepper.","Simmer 25 minutes until the vegetables are tender.","Add the pasta and cook until al dente, then stir the spinach through for the last minute.","Remove the bay leaf, tear the fresh basil over the top and finish with a drizzle of olive oil."]},
"Saag Chicken":{prepTime:"15 mins",cookTime:"25 mins",steps:["Cook the basmati rice according to package directions.","Blanch the spinach and mustard greens for a minute, then drop them into ice water to hold the colour.","Blend the greens with the ginger, garlic and serrano chile into a coarse puree - the aromatics go into the puree, not into the pan afterwards.","Dice the onion, chop the tomato and cut the chicken breast into pieces.","Crackle the cumin in the vegetable oil, then fry the onion until golden and add the tomato and cook it down.","Add the chicken and brown it, then stir in the greens puree with the turmeric, coriander powder and garam masala and simmer 15 minutes. Season with salt and black pepper.","Take the pan off the heat and swirl in the greek yogurt so it enriches the sauce without splitting, then scatter the cilantro over.","Serve over the rice."]},
"Stuffed Grape Leaves":{prepTime:"30 mins",cookTime:"45 mins",steps:["Rinse the brined grape leaves well and pat them dry, trimming off any stems.","Mix the RAW white rice with the ground lamb, the finely diced onion, the allspice, cinnamon, salt and black pepper. The rice must go in uncooked so it swells inside the roll as it absorbs the cooking liquid.","Lay a leaf vein-side up, put a small line of filling near the stem end, fold the sides in and roll it tight but not straining - the rice needs room to expand.","Pack the rolls seam-side down in a snug layer in a heavy pot.","Pour over the olive oil, the lemon juice and just enough water to cover, and weigh the rolls down with a plate so they hold their shape.","Simmer covered on low heat 45 minutes until the rice is tender and the leaves are soft. Serve warm or at room temperature."]},
"Doenjang Jjigae":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook the white rice according to package directions.","Slice the pork belly into thin pieces. Slice the zucchini and onion, cube the tofu, mince the garlic and slice the green onion and serrano chile.","Brown the pork belly in the pot for 3-4 minutes until crisp. Dissolve the doenjang in about one and a half cups of water or anchovy broth and pour it in.","Bring to a boil, add the zucchini and onion, and stir in the minced garlic and gochugaru.","Simmer 15 minutes until the vegetables are tender, seasoning with salt and black pepper.","Add the cubed tofu and the sliced serrano chile and simmer 3 minutes more, then scatter the green onion over. Serve bubbling hot alongside the rice with the kimchi on the side."]},
"Chicken Souvlaki Plate":{prepTime:"20 mins",cookTime:"15 mins",steps:["Cut the chicken breast into cubes and marinate them with the olive oil, the lemon juice, half the minced garlic, the oregano, paprika, salt and black pepper for at least 30 minutes.","Thread the chicken onto skewers - souvlaki means little skewer, and the cubes-on-a-stick form is the dish.","Grill 12-15 minutes, turning, until charred at the edges.","Grate the cucumber and squeeze the liquid out of it, then stir it into the greek yogurt with the rest of the garlic and the dill to make tzatziki.","Dice the tomato and thinly slice the red onion.","Warm the pita and serve the skewers with the tzatziki, tomato and red onion."]},
"Pulled Pork Sandwich":{prepTime:"10 mins",cookTime:"3 hrs",steps:["Season the pork shoulder generously with salt, black pepper, and smoked paprika.","Place it in a slow cooker or Dutch oven with about half a cup of water and cover tightly.","Cook on low for 3 hours until fork-tender.","Shred the pork with two forks and toss it with the BBQ sauce.","Split the whole wheat bread lengthwise into a roll shape and toast lightly.","Toss the coleslaw mix with the red wine vinegar and a pinch of salt and black pepper, then pile the pork on the bread and top with the slaw."]},
"Shrimp Scampi":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook the pasta in well-salted water until al dente, reserving a little of the water.","Slice the garlic thin.","Warm the olive oil and butter together and cook the garlic gently with the chili flakes until fragrant but not browned.","Add the white wine and simmer 1-2 minutes until slightly reduced.","Add the shrimp and cook 1-2 minutes per side until just pink. Season with salt and black pepper.","Stir in the lemon juice and the lemon zest, add the drained pasta with a splash of its water and toss to emulsify, then stir the chopped parsley through off the heat."]},
"Pad Pak Ruam Mit Goong":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook the white rice according to package directions - Thai food is eaten with jasmine rice.","Mix the sauce in a bowl first, as Thai cooks do, so it goes into the wok as one splash: fish sauce, soy sauce, sugar, salt, white pepper and the sesame oil, which belongs in the sauce rather than in the hot wok.","Peel and devein the shrimp. Mince the garlic, slice the bell pepper and carrot, and shred the cabbage.","Get the wok very hot, add the vegetable oil, then the garlic for about 20 seconds until golden.","Add the shrimp and toss continuously until just pink, then lift them out.","Stir-fry the carrot and cabbage first, then the bell pepper, for 2-3 minutes, keeping everything crisp.","Return the shrimp, pour in the sauce, and toss to coat.","Off the heat, add the green onion and sliced serrano chile to taste, then serve over the rice."]},
"Chicken Fried Rice":{prepTime:"10 mins",cookTime:"12 mins",steps:["Use day-old cooked white rice for best results. Dice the chicken breast and mince the garlic.","Heat the vegetable oil in a wok over high heat, cook the chicken until done, and set aside.","Scramble the egg in the wok and break it apart.","Add the minced garlic and the diced carrot and stir-fry for 2 minutes, then add the rice and green peas for a further 3-4 minutes, chopping to separate the grains.","Return the chicken, add the soy sauce, and season with salt and white pepper.","Off the heat, stir through the sliced green onion and the sesame oil. Serve immediately."]},
// Removed: Mujaddara cooking instructions
"Chicken Korma":{prepTime:"15 mins",cookTime:"25 mins",steps:["Cook the basmati rice according to package directions.","Slice the onion thin and fry it in the butter until deep golden, then lift most of it out and grind it to a paste - this fried-onion paste is the structural backbone of a korma and the dish had none.","Cut the chicken breast into pieces. Mince the garlic and ginger and slit the serrano chile.","Fry the garlic, ginger and chile in the remaining butter, add the chicken and seal it, then stir in the cumin, coriander powder, cardamom and cinnamon.","Whisk the gram flour into the greek yogurt, then stir it into the pan off the heat and return it to a bare simmer - the besan stabilises the yogurt so it thickens the sauce instead of splitting, and it does the job almond or cashew paste would do in a traditional korma.","Stir the fried-onion paste back in and simmer gently 12 minutes until the sauce coats the chicken. Season with salt, black pepper and white pepper.","Scatter with the chopped cilantro and serve over the rice."]},
"Beef Bulgogi Noodle Bowl":{prepTime:"15 mins",cookTime:"15 mins",steps:["Soak the sweet potato noodles in warm water for 10 minutes, then boil 5-6 minutes, drain and cut with scissors.","Slice the beef sirloin thinly and marinate in the soy sauce, grated Asian pear, minced garlic, honey, sesame oil and black pepper.","Slice the onion, julienne the carrot and slice the green onion.","Cook the marinated beef with the sliced onion in a hot skillet for 3-4 minutes until caramelised. Season with a pinch of salt.","Assemble the bowl with the noodles, the bulgogi and its pan juices, and the carrot.","Top with the sliced green onion and serve."]},
"Beef Meatballs & Zoodles":{prepTime:"15 mins",cookTime:"20 mins",steps:["Soak the panko breadcrumbs in the whole milk for 5 minutes to make a panade.","Mix the ground beef with the soaked panko, the egg, the minced garlic, half the parmesan, salt, black pepper, oregano and dried basil. Form into meatballs.","Brown the meatballs in the olive oil on all sides.","Add the tomato sauce, cover, and simmer for 15 minutes until the meatballs are cooked through.","Spiralize or ribbon-cut the zucchini into zoodles.","Saut\u00e9 the zoodles briefly in a hot pan for 2 minutes, then drain off the water they release.","Serve the meatballs and sauce over the zoodles with the remaining parmesan grated over."]},
"Lamb Tagine":{prepTime:"20 mins",cookTime:"1 hr 30 mins",steps:["Cube the lamb shoulder and sear it hard in the olive oil until well browned, then set it aside.","Slice the onion and soften it with the minced garlic.","Return the lamb, add the cumin, cinnamon, ground ginger, turmeric, paprika and the saffron, and stir until the spices coat everything and smell toasted.","Add the tomato sauce and about 1 cup of water - just enough to come partway up the meat, since a tagine braises in its own steam rather than boiling in liquid.","Cover and braise gently 1 hour, then add the carrot, eggplant and the chickpeas (soaked overnight and simmered until tender, about an hour) and cook 30 minutes more until the lamb pulls apart.","Season with salt and black pepper and scatter the chopped cilantro over before serving."]},
"Pesto Shrimp Pasta":{prepTime:"5 mins",cookTime:"15 mins",steps:["Cook the pasta in well-salted water until al dente, reserving a spoonful of the water.","Season the shrimp with salt and black pepper and cook them 1-2 minutes per side until just pink.","Make the pesto while the pasta cooks: pound or blitz the basil with the garlic and a pinch of salt, work in the grated parmesan, and stream in the olive oil to a loose paste - no nuts.","Loosen the pesto with the reserved pasta water off the heat - pesto is never cooked.","Toss the drained pasta and the shrimp through the pesto and serve. The parmesan stays inside the pesto - Italians do not grate more cheese over seafood pasta."]},
"Shoyu Chicken Ramen":{prepTime:"10 mins",cookTime:"25 mins",steps:["Simmer the shiitake mushroom, the smashed garlic and the sliced ginger in about 2 cups of water for 20 minutes to build the broth, then lift out the mushroom and slice it.","Poach the chicken breast in the broth until cooked through, about 12 minutes, then lift it out and slice it.","Soft-boil the egg 6-7 minutes, peel it and halve it.","Mix the soy sauce and mirin into a shoyu tare and stir it into the broth. Season with salt and white pepper.","Cook the ramen noodles in a separate pot of boiling water, about 3 minutes, and drain them well - never cook noodles in the broth or it goes cloudy and starchy.","Wilt the spinach in the hot broth for a minute.","Put the noodles in a bowl, ladle the broth over, and top with the sliced chicken, the egg, the spinach, the sliced shiitake and the green onion. Finish with the sesame oil."]},
"Mediterranean Tuna Salad":{prepTime:"10 mins",cookTime:"0 mins",steps:["Drain the canned tuna well and flake it into a bowl.","Cook the dried white beans (soaked overnight and simmered until tender, about an hour), drain and cool them, and add them.","Dice the cucumber and thinly slice the red onion.","Dress with the olive oil, the lemon juice, the oregano, dried parsley, salt and black pepper, and fold gently so the beans keep their shape.","Serve with the whole wheat bread."]},
"Beef & Broccoli":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook the white rice according to package directions.","Slice the beef sirloin thinly against the grain and toss it with half the cornstarch to velvet it.","Cut the broccoli into small florets and blanch for 2 minutes, then drain.","Stir the remaining cornstarch into the soy sauce with a splash of water to make a slurry.","Heat the vegetable oil in a wok over high heat and sear the beef for 2 minutes, then set aside.","Mince the garlic and ginger, stir-fry them for 30 seconds until fragrant, then add the blanched broccoli for 1-2 minutes.","Return the beef, pour in the slurry, and toss for 30-60 seconds until the sauce thickens and glosses. Season with salt and black pepper.","Finish off the heat with the sesame oil and serve over the rice."]},
"Burrito de Frijol con Queso":{prepTime:"10 mins",cookTime:"25 mins",steps:["Simmer the black beans until soft in about a cup of water, then drain them, keeping a little of the cooking liquid.","Heat the vegetable oil in a pan and refry the beans with the cumin, mashing them with the back of a spoon and loosening with the reserved liquid until thick and spreadable. Season with salt and black pepper.","Blister the bell pepper and onion over high heat until the skins char in spots, then cut them into strips and toss with the Mexican oregano and the minced jalapeno to make rajas con cebolla.","Warm the whole wheat tortilla in a dry pan until soft and flexible.","Spread the refried beans down the middle of the tortilla, lay the rajas over them and scatter the mozzarella on top.","Roll the burrito tightly, tucking in the sides, then set it seam-side down in the dry pan for a minute or two to seal and melt the cheese."]},
"Okonomiyaki":{prepTime:"15 mins",cookTime:"15 mins",steps:["Whisk the flour with about 1/3 cup of water into a loose batter and rest it in the fridge for at least an hour.","Shred the cabbage finely and slice the green onion.","Fold the cabbage, green onion and beaten eggs into the rested batter with the salt, folding rather than overmixing so the pancake stays light.","Lay the thin-sliced pork belly flat in a hot dry pan and let it begin to render.","Pour the batter over the pork and cook for 5-6 minutes per side until golden and set through.","Brush the pancake with tonkatsu sauce, pipe the mayonnaise over it in a lattice, and finish with shredded nori and a pinch of shichimi togarashi."]},
"Paneer Tikka Wrap":{prepTime:"20 mins",cookTime:"10 mins",steps:["Toast the gram flour in a dry pan for a minute, then whisk it into the greek yogurt with the minced ginger and garlic, the cumin, turmeric, garam masala, coriander powder, paprika, salt and black pepper. The besan is what makes the marinade cling to the paneer instead of sliding off.","Cut the paneer into cubes and fold it through the marinade. Leave it 15 minutes.","Cut the bell pepper and onion into squares.","Grill or pan-sear the paneer and vegetables until charred at the edges.","Squeeze the lemon juice over the hot paneer and toss through the chopped cilantro.","Warm the tortilla in a dry pan, pile the paneer and vegetables down the middle, roll it up tightly and serve."]},
"Shrimp Spinach & Rice Salad":{prepTime:"10 mins",cookTime:"12 mins",steps:["Cook the brown rice according to package directions and let it cool.","Peel and devein the shrimp. Sear in a little of the olive oil over high heat for 1-2 minutes per side until pink, then set aside to cool slightly.","Wash the spinach and slice the avocado.","Toss the spinach, brown rice, avocado and shrimp together.","Whisk the remaining olive oil with the lemon juice, dress the salad, and season with salt and black pepper."]},
"Lamb Gyro":{prepTime:"15 mins",cookTime:"20 mins",steps:["Mix the ground lamb with half the minced garlic, the cumin, oregano, salt and black pepper and knead it until it turns sticky and paste-like.","Press the seasoned lamb into a thin loaf and cook it in a hot skillet 3-4 minutes per side, then rest it and slice it thinly across - a gyro is shaved slices off a loaf, not crumbles.","Grate the cucumber and squeeze it dry, then stir it into the greek yogurt with the rest of the garlic and the lemon juice to make tzatziki.","Dice the tomato and thinly slice the red onion.","Warm the pita, spread the tzatziki over it, and fill with the sliced lamb, the tomato and the red onion."]},
"Lomo Saltado":{prepTime:"15 mins",cookTime:"15 mins",steps:["Cut beef sirloin into thick strips and season with garlic, cumin, salt and pepper. Cut red onion and tomato into thick wedges, and slice the aji amarillo paste into the mix later. Have everything ready before you start - the cooking takes under 5 minutes.","Cut potato into thick batons and fry in hot oil until golden and crisp. Drain, salt, and keep hot.","Cook white rice according to package directions.","Heat a wok or wide steel pan until it is smoking. Add olive oil, then the beef in a single layer. Leave it undisturbed 1-2 minutes to sear hard, then toss. Work in batches so the meat sears rather than steams.","Add red onion and aji amarillo paste and toss 30-60 seconds so the onion stays crisp-tender. Deglaze the pan with red wine vinegar.","Add the tomato wedges and soy sauce and toss just 30 seconds - the tomato should hold its shape and release a little juice.","Fold in the hot fried potatoes (or pile them alongside), scatter with cilantro, and serve immediately with the rice molded to one side."]},
"Pollo Guisado":{prepTime:"40 mins",cookTime:"35 mins",steps:["Finely chop the onion, bell pepper, garlic and half the cilantro into a sofrito paste.","Rub the chicken thighs with the sofrito, the lime juice, oregano, cumin, adobo, culantro, salt and black pepper, and marinate at least 30 minutes.","Scrape the marinade off the chicken and reserve it. Heat the olive oil in a Dutch oven over medium heat, add the sugar, and let it melt and darken to a copper caramel.","Add the chicken to the caramelised sugar and brown 3-4 minutes per side until the pieces take on a deep mahogany colour.","Stir in the reserved sofrito and the tomato sauce, then add enough water to come halfway up the chicken, about three quarters of a cup.","Add the diced potato and carrot, cover, and simmer 25-30 minutes until the chicken and potato are tender and the sauce has thickened.","Scatter the remaining cilantro over the stew and serve."]},
"Feijoada":{prepTime:"20 mins",cookTime:"2 hrs 30 mins",steps:["Soak the black beans overnight, then drain them.","Cut the pork belly and pork loin into cubes and season them with salt and black pepper.","Heat the olive oil in a heavy pot and brown the pork belly until its fat renders, then add the pork loin and brown that too.","Add most of the diced onion and the minced garlic and cook 3 minutes until softened, reserving a spoonful of onion for the farofa.","Add the drained beans, the bay leaves and about 1 cup of water, then simmer covered for 2-3 hours, adding more water as it reduces, until the liquor is dark and thick. Mash a ladle of beans against the side of the pot to thicken it.","Cook the white rice according to package directions.","For the farofa, melt half the butter in a skillet, soften the reserved onion, then stir in the cassava flour over low heat and toast it, stirring constantly, until it is golden and sandy.","For the couve, shred the kale into fine ribbons and flash-saute it in the remaining butter for 2 minutes so it stays bright green.","Remove the bay leaves and serve the beans over the rice with the farofa, the couve and slices of fresh orange alongside."]},
"Moqueca":{prepTime:"25 mins",cookTime:"15 mins",steps:["Peel and devein the shrimp, then marinate them with the lime juice, the minced garlic and a good pinch of salt for 20 minutes.","Cook the white rice according to package directions.","Slice the onion, tomato and bell pepper into rounds rather than dicing them.","Layer the onion, tomato and bell pepper in the bottom of a heavy pot or clay panela with half the cilantro, and season with salt, black pepper and the cayenne.","Lay the marinated shrimp on top of the vegetables without stirring.","Pour the coconut milk and the palm oil over everything, cover, and cook gently 8-10 minutes until the shrimp turn pink. Do not stir and do not brown anything.","Scatter the remaining cilantro and the sliced green onion over the top and serve straight from the pot, spooning the broth over the rice."]},
"Paella Mixta":{prepTime:"15 mins",cookTime:"30 mins",steps:["Dice the bell pepper and mince the garlic. Trim the green beans and halve them. Grate the tomato on a box grater and discard the skin.","Heat the olive oil in a wide pan. Brown the chicken thigh pieces for 4-5 minutes, then remove them.","Add the bell pepper and garlic and cook 2 minutes, then the grated tomato and the paprika, and fry it down to a dark sofrito, about 5 minutes.","Crumble the saffron into 180 ml of warm water or broth and let it steep. Add the short-grain rice, spread it evenly across the pan, pour in the saffron liquid and stir once. Season with salt and black pepper.","Return the chicken and add the green beans and green peas. Do not stir again.","Simmer 18-20 minutes until the rice has absorbed the liquid, adding the shrimp for the last 5 minutes. Raise the heat to high for the final 2 minutes until you hear the base crackle - that is the socarrat. Rest 5 minutes before serving."]},
"Ceviche de Pescado":{prepTime:"20 mins",cookTime:"20 mins",steps:["Boil the sweet potato whole until fork-tender, about 15-20 minutes. Cool and slice into thick rounds. Boil the corn and cut the kernels from the cob.","Slice the red onion very thinly. Salt it, rest 10 minutes, then rinse and drain well to take out the harshness.","Cut the sea bass into even 2cm cubes with a sharp knife. Pat dry - never rinse the fish under water.","Season the fish in a cold bowl with salt, pepper, and minced aji limo, tossing gently.","Pour the lime juice directly over the fish - if squeezing it fresh, avoid twisting the rinds, which turns the juice bitter. Stir gently and let it cure just 2-5 minutes - the cubes should stay translucent at the center, not turn chalky.","Fold in the drained red onion and chopped cilantro. Taste and correct the salt.","Serve immediately and cold, with the sweet potato rounds and corn alongside. The milky juice left in the bowl is the leche de tigre."]},
"Arroz con Pollo":{prepTime:"15 mins",cookTime:"35 mins",steps:["Finely chop the onion, bell pepper, garlic and half the cilantro into a sofrito.","Season the chicken thighs with half the sofrito plus cumin, oregano, culantro, salt and black pepper, and let them sit 15 minutes.","Heat the olive oil in a caldero or heavy pot, brown the chicken 4 minutes per side, and remove it.","Add the remaining sofrito to the pot with the annatto and coriander powder and cook 3 minutes until the oil turns orange-gold.","Stir in the rice and tomato sauce so every grain is coated, then pour in about three quarters of a cup of chicken stock.","Nestle the chicken back into the rice, cover, and cook 20 minutes without stirring so a pegao crust forms on the bottom.","Scatter the green peas over the top, cover 2 more minutes, then fold through the remaining cilantro and rest 5 minutes before serving."]},
"Gambas al Ajillo":{prepTime:"5 mins",cookTime:"10 mins",steps:["Peel and devein the shrimp. Slice the garlic thinly.","Heat the olive oil in a small skillet or earthenware cazuela over low heat. Add the sliced garlic and cook gently 3-4 minutes until pale gold and fragrant - do not let it brown or the oil turns bitter.","Raise the heat, add the shrimp and the chili flakes, and cook 1-2 minutes per side until pink and just curled. Season with salt and black pepper.","Off the heat, pour in the dry sherry and stir in the dried parsley, swirling the pan to emulsify the oil.","Squeeze the lemon juice over the shrimp and toast the whole wheat bread.","Serve immediately in the pan, still sizzling, with the toasted bread for mopping up the garlic oil."]},
"Aji de Gallina":{prepTime:"15 mins",cookTime:"30 mins",steps:["Poach the chicken breast in lightly salted water for 20-25 minutes at a bare simmer. Remove, cool, and hand-shred into fine threads. Keep the broth.","Boil the potato until tender and slice thick. Hard-boil the egg. Cook the white rice according to package directions.","Soak the bread in a little of the hot broth until completely soft, then blend smooth.","Sweat the finely chopped red onion in olive oil until translucent, add garlic and cook 1 minute more.","Add the aji amarillo paste and fry it hard until the oil separates and the color deepens - this cooks out the raw chili taste and is the step most often skipped.","Stir in the blended bread and cook until it thickens and pulls from the pan. Add the shredded chicken and evaporated milk and simmer gently, without boiling. Take off the heat and stir in the grated parmesan.","Lay the potato slices down, spoon the sauce over them, and serve with rice alongside, garnished with the hard-boiled egg."]},
"Causa Limena":{prepTime:"30 mins",cookTime:"25 mins",steps:["Boil the potatoes whole and unpeeled in salted water until tender. Peel them while still hot and pass through a ricer immediately - never add water.","Let the puree cool to room temperature, then knead in the aji amarillo paste, lime juice, olive oil and salt until the mass is smooth, elastic and evenly yellow. It should taste distinctly limey and gently spicy.","Poach the chicken breast until cooked through, cool, and shred finely. Bind it with the mayonnaise, a squeeze of lime juice, salt and pepper.","Hard-boil the egg. Slice the avocado.","Oil a ring mold or small loaf pan. Press in half the potato masa firmly and flat, layer on the avocado, then the chicken filling.","Press the remaining masa over the top, level it, and refrigerate at least 30 minutes so it sets and holds its shape.","Unmold onto the lettuce, garnish with the hard-boiled egg, and serve cold."]},
"Tallarines Verdes con Bistec":{prepTime:"15 mins",cookTime:"20 mins",steps:["Bring a large pot of well-salted water to the boil for the pasta.","Saute the finely chopped red onion in olive oil until soft and translucent, then add the garlic and cook until fragrant.","Add the spinach and basil and cook just until wilted and the moisture has cooked off, 2-3 minutes. Season with salt and pepper.","Blend the pan contents with the evaporated milk, queso fresco and parmesan until completely smooth and thick. Season at the end - queso fresco varies a lot in saltiness.","Cook the pasta al dente and reserve a cup of the cooking water.","Season the beef sirloin and sear it hard in a hot pan to your liking, then rest it and slice.","Return the green sauce to low heat, add the drained pasta and toss 2 minutes so it coats and clings, loosening with pasta water as needed. Plate the pasta, lay the steak over it, and finish with black pepper."]},
"Ropa Vieja":{prepTime:"40 mins",cookTime:"3 hrs 30 mins",steps:["Cook the white rice according to package directions.","Mash the garlic with the adobo, oregano, cumin and black pepper into a paste and rub it over the flank steak. Marinate at least 30 minutes.","Heat the olive oil in a heavy pot and sear the steak 3 minutes per side, then set it aside.","Add the sliced onion and bell pepper to the pot with the smoked paprika and cook 6-8 minutes until soft and sweet.","Deglaze with the white wine and let it reduce by half, then stir in the tomato sauce, the bay leaves and about 1 cup of water.","Return the steak to the pot, cover, and braise on low heat for 3 hours until it pulls apart with no resistance.","Remove the bay leaves and shred the beef with two forks directly in the sauce, then simmer uncovered 10-15 minutes to marry.","Season with salt, finish with the chopped cilantro, and serve over the rice with the lime juice sprinkled over."]},
"Picanha with Farofa":{prepTime:"15 mins",cookTime:"20 mins",steps:["Cook the white rice and the black beans separately according to package directions.","Dice the tomato, the red onion and the bell pepper small for the vinagrete, dress them with the red wine vinegar, salt and black pepper, and let them sit 10 minutes.","Score the fat cap of the beef in a crosshatch and season it generously with coarse salt.","Sear the beef fat-side down first until the cap renders and browns deeply, then turn it and cook 3-4 minutes on the meat side for medium-rare. Rest it 5 minutes.","For the farofa, melt the butter in a skillet, soften the diced onion and the minced garlic, then stir in the cassava flour over low heat and toast it, stirring constantly, until it is golden and sandy. Season with salt.","Slice the steak against the grain and serve it with the rice, the beans, the farofa and a spoonful of vinagrete."]},
"Tortilla Espanola":{prepTime:"10 mins",cookTime:"25 mins",steps:["Peel the potato and slice it thinly, about 2-3 mm. Slice the onion finely.","Heat the olive oil in a non-stick skillet over low heat and add the potato and onion. Cook gently 15-20 minutes, turning occasionally, until completely tender - they should poach in the oil, not brown or crisp. Drain, reserving the oil.","Beat the eggs with salt and black pepper in a large bowl. Fold in the hot potato and onion and let the mixture rest 10 minutes so the potato absorbs the egg.","Return a little of the reserved oil to the skillet and pour in the mixture over medium-low heat.","Cook 6-8 minutes until the bottom is set. Flip using a plate and cook 4 more minutes.","Slide onto a plate and serve warm or at room temperature."]},
"Beef Pho":{prepTime:"15 mins",cookTime:"45 mins",steps:["This is an honest weeknight shortcut broth, not a from-scratch pho: real pho bo simmers beef bones for six hours or more, and good store-bought beef broth stands in for that here.","Char the onion and the ginger directly over a flame or under the broiler until blackened in patches, then scrape off the worst of the char.","Dry-toast the star anise, cinnamon, cardamom and coriander in a dry pan until fragrant, about 2 minutes, then tie them in a spice bag or a square of cheesecloth.","Simmer about 2 cups of beef broth, uncovered, with the charred onion and ginger and the spice bag for 30-40 minutes.","Season the broth with the fish sauce, sugar and salt, tasting as you go.","Cook the rice noodles, the flat banh pho, according to package directions, drain, and put them in the bowl.","Slice the beef sirloin paper-thin against the grain and fan the raw slices over the noodles.","Strain the broth and pour it boiling over the beef; the heat cooks the thin slices through.","Serve with the bean sprouts, basil, cilantro, green onion and the lime juice alongside, added at the table."]},
"Chicken Pho":{prepTime:"15 mins",cookTime:"40 mins",steps:["Char the onion and the ginger over a flame or under the broiler until blackened in patches; charred ginger is the aromatic that makes this pho ga rather than plain chicken soup.","Dry-toast the coriander, star anise and cinnamon until fragrant and tie them in a spice bag; the spicing here is deliberately lighter than in beef pho.","Simmer about 2 cups of chicken broth with the charred aromatics and the spice bag, poaching the chicken breast in it for 12-15 minutes until just cooked through.","Lift the chicken out and hand-shred it rather than slicing it into strips, then let the broth carry on simmering another 15-20 minutes.","Season the broth with the fish sauce, sugar and salt.","Cook the rice noodles separately according to package directions and drain.","Put the noodles in the bowl, pile the shredded chicken over them, and ladle the broth through a strainer.","Serve with the bean sprouts, cilantro, green onion, basil and the lime juice alongside, added at the table."]},
"Bun Tom Nuong":{prepTime:"25 mins",cookTime:"10 mins",steps:["Julienne the carrot and daikon and quick-pickle them in the rice vinegar with a little of the sugar and a pinch of salt for 30 minutes; this is do chua.","Whisk the nuoc cham: fish sauce, lime juice, the rest of the sugar, a splash of warm water, minced garlic and sliced serrano chile, tasting until it balances sour, salty and sweet. This dressing is the dish, not a condiment on the side.","Set a spoonful of the fish sauce and garlic mixture aside and marinate the shrimp in it for 15 minutes.","Cook the rice noodles, the round bun vermicelli, then drain, rinse cold and drain well.","Grill or sear the shrimp over high heat until charred at the edges.","Fry the sliced shallot in the vegetable oil until golden and crisp and drain it, then stir the green onion into a little of the warm oil to make scallion oil.","Build the bowl: shredded romaine lettuce and bean sprouts at the bottom, cold noodles over them, then the cucumber, the pickled carrot and daikon, mint and cilantro.","Top with the grilled shrimp, the scallion oil and the crispy fried shallots, which are the traditional nut-free crunch here.","Pour the nuoc cham over at the table and toss everything together."]},
"Tuna Tataki Bowl":{prepTime:"15 mins",cookTime:"10 mins",steps:["Cook white rice according to package directions and leave it unseasoned.","Pat the ahi tuna dry, season it with salt, and sear it in a smoking-hot pan for 20-30 seconds per face so every side browns.","Plunge the seared block straight into ice water for 10 seconds, pat it completely dry, and chill it for 15 minutes.","Slice the chilled tuna across the grain into 6-8mm slices.","Cook the edamame in boiling water for 3 minutes and drain it; slice the cucumber thinly and shave the red onion paper-thin.","Grate the daikon and the ginger and slice the green onion.","Whisk the soy sauce with the lemon juice and the mirin to make a ponzu.","Arrange the rice in a bowl, lay the tuna over it with the cucumber, red onion and edamame, top with the grated daikon, grated ginger and green onion, and spoon the ponzu over."]},
"Chicken Yakitori Bowl":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook white rice according to package directions.","Simmer the soy sauce, mirin, sake and sugar together until reduced by about a third into a glossy tare, then season it with a pinch of salt.","Cut the chicken thigh into bite-sized pieces and cut the green onion into 3cm batons.","Thread the chicken onto skewers alternating with the green onion batons so the negi chars between the pieces.","Grill the skewers over charcoal, or under a very hot broiler, turning often for 6-8 minutes, and brush them with the tare only during the second half of cooking so it caramelises without burning; a hot pan works as a fallback.","Serve the skewers over the rice with any remaining tare spooned across."]},
"Greek Lemon Chicken":{prepTime:"15 mins",cookTime:"45 mins",steps:["Cut the potato into thick wedges and toss them with half the olive oil, half the lemon juice, the lemon zest, the oregano, salt and black pepper.","Season the chicken breast and sear it in the remaining olive oil with the sliced red onion and the minced garlic until the onion softens.","Move the chicken and onion into a roasting dish with the potato wedges and pour the rest of the lemon juice over.","Roast at 190C for 40 minutes, basting once, until the potatoes have absorbed the lemon and gone golden at the edges.","Wilt the spinach and serve it alongside."]},
"Seared Tuna Steak":{prepTime:"10 mins",cookTime:"10 mins",steps:["Season the ahi tuna generously with salt and black pepper.","Heat a little of the olive oil in a heavy pan until almost smoking and sear the tuna 1-2 minutes per side, leaving the centre rare.","Wilt the spinach in the same pan.","Whisk the remaining olive oil with the minced garlic, the lemon juice and the oregano into a dressing.","Slice the tuna across the grain, plate it with the spinach and the sliced cucumber, and spoon the dressing over."]},
"Turkey & Broccoli Bowl":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook the brown rice according to package directions.","Slice the turkey breast into strips and mince the garlic.","Heat the olive oil in a pan, season the turkey with salt and black pepper, and cook the strips for 2-3 minutes, turning once, until just golden and cooked through.","Steam or blanch the broccoli for 3-4 minutes until bright green.","Add the minced garlic and the soy sauce to the pan in the last 30 seconds and toss to coat the turkey.","Serve the turkey and broccoli over the rice."]},
"Chicken & Sweet Potato Bowl":{prepTime:"10 mins",cookTime:"25 mins",steps:["Peel and cube the sweet potato. Toss with about a third of the olive oil and roast at 200\u00b0C (400\u00b0F) for 20 minutes.","Mince the garlic and rub the chicken breast with it, plus salt and black pepper.","Pan-sear the chicken in a little more of the olive oil for 6-7 minutes per side until cooked through, then slice.","Dice the onion and saut\u00e9 it in the remaining olive oil until softened and golden, 5-6 minutes, then add the spinach and wilt briefly.","Arrange the roasted sweet potato, the sliced chicken, and the onion and spinach in a bowl."]},
"Shrimp Fajitas":{prepTime:"15 mins",cookTime:"10 mins",steps:["Peel and devein the shrimp, then toss them with the lime juice, minced garlic, cumin, Mexican oregano, salt and black pepper and leave them to marinate for 10 minutes.","Slice the bell pepper and onion into strips.","Heat a skillet over high heat and sear the shrimp 2-3 minutes per side, then set them aside.","In the same pan, cook the bell pepper and onion strips for 3-4 minutes until charred at the edges but still crisp.","Warm the tortilla in a dry pan.","Fill the tortilla with the shrimp, peppers and onion, and finish with chopped cilantro."]},
"Tandoori Chicken":{prepTime:"20 mins",cookTime:"20 mins",steps:["Cut deep diagonal slashes into the chicken thigh, down to the bone. Rub it with half the lemon juice, the salt and a little of the paprika and leave it 15 minutes - this first marinade is what seasons the meat itself.","Whisk the greek yogurt with the minced garlic and ginger, the cumin, garam masala, the rest of the paprika, the cayenne, black pepper and the olive oil.","Coat the slashed chicken in the yogurt marinade, working it into the cuts, and refrigerate as long as you can - four hours if possible, overnight is better.","Grill or bake at 220C for 15-20 minutes until charred at the edges and cooked through.","Cook the basmati rice and slice the onion into rings.","Pour the remaining lemon juice over the chicken and serve with the rice and the raw onion rings."]},
"Jerk Chicken with Rice and Peas":{prepTime:"20 mins",cookTime:"1 hr",steps:["Soak the kidney beans overnight, then drain and simmer them in about 1 cup of fresh water until tender, roughly 45 minutes.","Blend the green onion, garlic, ginger, serrano chile, allspice, thyme, cinnamon, soy sauce, honey and the lime juice into a thick wet paste.","Coat the chicken thighs in the paste, cover, and marinate at least 4 hours and ideally overnight.","Add the white rice and the coconut milk to the beans and their liquid, top up so the rice is just covered, cover the pot and cook 18-20 minutes until the liquid is absorbed.","Grill or pan-sear the marinated chicken 6-7 minutes per side, letting the outside char - jerk should taste smoky.","Dice the bell pepper and onion and saute them briefly until just softened.","Rest the chicken, slice it against the grain, and serve over the rice and peas with the peppers and onion alongside."]},
"Pollo a la Plancha":{prepTime:"20 mins",cookTime:"15 mins",steps:["Butterfly or pound the chicken breast to an even thickness so it cooks fast and stays juicy.","Whisk a marinade of olive oil, minced garlic, half the lime juice, cumin, oregano, salt and pepper. Coat the chicken and leave it 15-30 minutes.","Make the salsa criolla: slice the red onion into a very fine julienne, soak it in cold water 10-15 minutes, then drain thoroughly. Toss with aji amarillo paste, the remaining lime juice, chopped cilantro, salt and pepper, and let it rest 10 minutes.","Cook white rice according to package directions.","Get a flat griddle or heavy pan properly hot. Lay the chicken down and leave it undisturbed 4-5 minutes per side until deeply golden and just cooked through.","Rest the chicken 2-3 minutes. Plate with the rice, a simple romaine and tomato salad, and a generous mound of salsa criolla over the chicken."]},
"Turkey Lettuce Wraps":{prepTime:"15 mins",cookTime:"10 mins",steps:["Dice the turkey breast small.","Heat the sesame oil in a pan over medium-high heat and cook the diced onion, garlic, and ginger for 1 minute until fragrant.","Add the turkey and cook 4-5 minutes until golden, seasoning with salt, black pepper, and white pepper.","Add the soy sauce and hoisin sauce and toss to glaze in the last minute.","Grate or julienne the carrot into thin strips.","Separate the butter lettuce leaves to use as cups.","Fill the lettuce cups with the turkey and carrot, scatter with the sliced green onion, and sprinkle the lime juice over the top."]},
"Turkey Kofta Plate":{prepTime:"20 mins",cookTime:"12 mins",steps:["Pulse the turkey breast in a food processor until coarsely ground, or use ground turkey.","Mix it with the minced garlic, the finely chopped parsley, the cumin, coriander powder, allspice, salt and black pepper, and knead until sticky.","Rest the mixture 20 minutes, then shape it into flattened fingers.","Grill or broil 5-6 minutes per side until browned and cooked through.","Grate the cucumber, squeeze it dry and stir it into the greek yogurt with the mint - this is khyar bi laban, the Levantine yogurt-cucumber side.","Slice the red onion thinly and serve the kofta with the khyar bi laban, the hummus, the red onion and the warm pita."]},
"Turkey and Vegetable Stir Fry":{prepTime:"10 mins",cookTime:"15 mins",steps:["Cook the white rice according to package directions.","Slice the turkey breast into thin strips. Mince the garlic and grate the ginger.","Heat the vegetable oil in a wok over high heat.","Add the garlic and ginger and stir-fry 30 seconds until fragrant.","Add the turkey strips and stir-fry 3-4 minutes until browned.","Add the sliced bell pepper and broccoli florets and stir-fry 3 more minutes.","Splash in the soy sauce and toss, then take the wok off the heat and stir the sesame oil through. Season with salt and white pepper.","Serve over the rice."]},
"Turkey Burrito Bowl":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook brown rice according to package directions.","Season turkey breast strips with cumin, paprika, salt, and pepper.","Cook turkey in a hot pan for 4-5 minutes per side until done. Slice.","Soak the dried black beans overnight and simmer them until tender, about an hour, then warm them in a small pot with a pinch of cumin.","Dice onion and chop cilantro.","Assemble bowl with rice, turkey, black beans, corn, onion, and cilantro. Spoon the lime juice over top."]},
"Lean Beef Tacos":{prepTime:"10 mins",cookTime:"10 mins",steps:["Brown the ground beef in a skillet over medium-high heat with the diced onion, breaking it apart, for six to eight minutes.","Season with cumin, guajillo chile, Mexican oregano, garlic powder, salt and black pepper.","Warm the corn tortillas in a dry pan for thirty seconds per side.","Chop the cilantro finely.","Fill the tortillas with the seasoned beef, onion and cilantro.","Sprinkle the lime juice over the tacos and serve with a salsa alongside - Mexican tacos are dressed at the table."]},
"Five-Spice Duck Stir Fry with Rice":{prepTime:"20 mins",cookTime:"15 mins",steps:["Cook the white rice according to package directions.","Slice the duck breast thinly against the grain and marinate it for 15 minutes in half the cornstarch, half the dry sherry, a little of the soy sauce, the five-spice and the white pepper; this is velveting, and the marinade is where five-spice belongs rather than as a dry rub.","Mix the sauce separately: the hoisin sauce, the remaining soy sauce and dry sherry, the sugar, the salt, and the rest of the cornstarch slaked in a spoonful of cold water.","Mince the garlic and grate the ginger.","Get the wok smoking hot, add the vegetable oil, then the garlic and ginger for 20-30 seconds until fragrant.","Add the duck, spread it in a single layer and let it sear before tossing, 2-3 minutes.","Add the shredded cabbage and stir-fry 2 minutes, keeping it crisp.","Pour the sauce down the side of the wok and toss until it thickens and glosses the duck.","Off the heat, toss through the green onion and the sesame oil, which is a finishing oil here, then serve over the rice."]},
"Peking-Style Duck Wraps":{prepTime:"10 mins",cookTime:"15 mins",steps:["Score the duck breast skin in a crosshatch without cutting into the meat, and season it with the salt and white pepper.","Place the duck skin-side down in a cold, dry pan and bring it up to medium heat, rendering for 6-8 minutes until the fat has run out and the skin is deep golden and glassy.","Flip the duck for 2 minutes, rest it 5 minutes, then slice it thinly.","Cut the cucumber into thin batons and the green onion into long fine julienne strips to match.","Warm the flour tortilla in a dry pan for 30 seconds per side; it stands in for the thin steamed Mandarin pancakes.","Smear the tortilla with the hoisin sauce, lay on the duck, cucumber and green onion, roll and serve."]},
"Duck Confit with Lentils":{prepTime:"15 mins",cookTime:"3 hrs",steps:["Rub the duck leg all over with the salt, black pepper, thyme and a crushed garlic clove. Cover and refrigerate 12-24 hours to cure.","Rinse the cure off the leg and dry it thoroughly. Melt enough duck fat to submerge it and poach at 90C / 195F for 2-3 hours, until the meat pulls easily from the bone.","Dice the carrot, onion and celery. Mince the remaining garlic.","Sweat the carrot, onion, celery and garlic in a spoonful of the duck fat until softened.","Add the green lentils, a bay leaf and about 200 ml of water or stock. Simmer 25-30 minutes until the lentils are tender but still holding their shape, then stir in the red wine vinegar.","Lift the leg out of the fat and crisp it skin-side down in a hot dry pan 3-4 minutes until the skin is golden and shatters.","Remove the bay leaf, spoon the lentils into a bowl and set the duck leg on top."]},
"Pan-Seared Duck Breast with Cherry Sauce & Potatoes":{prepTime:"10 mins",cookTime:"25 mins",steps:["Peel and slice the potato into thin rounds.","Score the duck breast skin in a crosshatch pattern. Season both sides with salt, black pepper and thyme.","Place the duck breast skin-side down in a cold pan over medium-low heat. Render the fat about 10 minutes until the skin is crispy and golden.","Flip the duck and cook 3 more minutes for medium-rare. Move it to a board and rest 5-10 minutes.","Pour off most of the fat the duck has rendered, reserving it. Fry the potato slices in the reserved fat over medium heat 10-12 minutes, turning, until golden and tender. Season with salt.","Add the finely diced shallot to the pan and sweat 1 minute. Add the red wine vinegar and let it hiss away, then add the cherries (frozen pitted dark sweet cherries, straight from the bag) and the honey with a splash of water. Simmer 4-5 minutes, crushing a few cherries against the pan, until the juices reduce to a syrupy sauce. Take off the heat and swirl in the butter.","Trim the asparagus and steam 4 minutes until tender-crisp.","Slice the duck thinly across the grain. Plate with the potatoes and asparagus, and spoon the cherry sauce over the duck."]},
"Tacos de Pato":{prepTime:"15 mins",cookTime:"3 hrs",steps:["Rub the duck leg with salt, black pepper, Mexican oregano, garlic powder and a splash of the lime juice, then let it rest for thirty minutes.","Slow-cook the duck leg submerged in its own rendered fat at 90C / 195F for two to three hours until it shreds easily.","Shred the meat with two forks, discarding the bones, then crisp the skin separately in a hot dry pan until it snaps like chicharron and crumble it over the meat.","Spread the shredded duck out in the hot pan and let the edges caramelise.","Warm the corn tortillas in a dry pan for thirty seconds per side.","Mash the avocado with the minced serrano chile and lime juice into a loose salsa.","Fill each tortilla with the duck, finely chopped white onion and cilantro, spoon the avocado salsa over and spoon more lime juice on top."]},
"Baked Cod with Lemon & Herbs":{prepTime:"10 mins",cookTime:"20 mins",steps:["Cook white rice according to package directions. Steam or blanch broccoli until tender-crisp, about 4 minutes.","Preheat oven to 200\u00b0C (400\u00b0F).","Place cod fillets on a lined baking sheet. Season with salt, pepper, oregano, parsley, the lemon zest, and minced garlic.","Drizzle with olive oil and squeeze lemon juice over the fish.","Bake for 12-15 minutes until fish flakes easily with a fork.","Serve cod over rice with broccoli on the side."]}
};

